<?php page_header(t($page),t($page === 'reports' ? 'reports_text' : ($page === 'newsletter' ? 'newsletter_text' : 'documents_text'))); ?>
<?php if ($page === 'reports'): ?><div class="source-panel"><?= icon('file-text') ?><h2><?= e(t('reports')) ?></h2><p><?= e(t('source_only')) ?></p><?php source_link('audit'); ?></div><?php else: ?>
<?php if ($page === 'newsletter'): ?><div class="notice"><p><?= e(t('source_only')) ?></p><?php source_link('csonewsletter'); ?></div><?php endif ?>
<div class="document-list"><?php foreach ($repository->all('documents') as $document): ?><article class="document-row"><?php if ($document['image']): ?><img src="<?= e($document['image']) ?>" alt="<?= e($document['title']) ?>" width="90" height="120" loading="lazy"><?php else: ?><span class="document-icon"><?= icon('file-text') ?></span><?php endif ?><div><h2 lang="uz-Latn"><?= e($document['title']) ?></h2><p><?= e(t('document_language')) ?> · PDF · <?= number_format($document['size']/1048576,1) ?> MB</p><a class="source-reference" href="<?= e($document['source']) ?>" target="_blank" rel="noopener"><?= e(t('source')) ?></a></div><a class="button button-secondary" href="<?= e($document['url']) ?>" download><?= e(t('download')) ?><?= icon('download-simple') ?></a></article><?php endforeach ?></div>
<?php endif ?>
